{"code": "fen = "r1b1k1nr/2pn1ppp/2N5/p7/P7/4B3/2P1BPPP/Q4RK1 w k - 1 17"

import itertools

def parse_fen(f):
    return f.split(' ')[0]

# Let's do a shallow minimax with simple material eval from white's perspective.
# Use python chess directly.

import chess
board = chess.Board(fen)

piece_val = {chess.PAWN:1, chess.KNIGHT:3, chess.BISHOP:3, chess.ROOK:5, chess.QUEEN:9, chess.KING:0}

def evaluate(b):
    score = 0
    for sq in chess.SQUARES:
        p = b.piece_at(sq)
        if p:
            v = piece_val[p.piece_type]
            if p.color == chess.WHITE:
                score += v
            else:
                score -= v
    return score

def minimax(b, depth, alpha, beta, maximizing):
    if depth == 0:
        return evaluate(b)
    if b.is_game_over():
        r = b.result()
        if r == '1-0': return 9999
        if r == '0-1': return -9999
        return 0
    moves = list(b.legal_moves)
    if maximizing:
        val = -99999
        for m in moves:
            b.push(m)
            val = max(val, minimax(b, depth-1, alpha, beta, False))
            b.pop()
            alpha = max(alpha, val)
            if alpha >= beta:
                break
        return val
    else:
        val = 99999
        for m in moves:
            b.push(m)
            val = min(val, minimax(b, depth-1, alpha, beta, True))
            b.pop()
            beta = min(beta, val)
            if alpha >= beta:
                break
        return val

cands = ["c6a5","c6e5","f1b1","e3c5","a1b1","a1b2","a1c3","c2c4","e2d1","e3f4","c6d4","f2f4"]
results = []
for mv in cands:
    m = chess.Move.from_uci(mv)
    if m not in board.legal_moves:
        continue
    board.push(m)
    # now it's black to move; evaluate with minimax depth 3 (black to move)
    val = minimax(board, 3, -99999, 99999, False)
    board.pop()
    results.append((val, mv))
    print(mv, val)

results.sort(reverse=True)
print("best:", results[:5])
"}

