board = chess.Board(fen)

piece_val = {chess.PAWN:1, chess.KNIGHT:3, chess.BISHOP:3, chess.ROOK:5, chess.QUEEN:9, chess.KING:0}

def evaluate(b):
    score = 0
    for sq in chess.SQUARES:
        p = b.piece_at(sq)
        if p:
            v = piece_val[p.piece_type]
            score += v if p.color == chess.WHITE else -v
    return score

def minimax(b, depth, alpha, beta, maximizing):
    if b.is_game_over():
        r = b.result()
        if r == '1-0': return 9999+depth
        if r == '0-1': return -9999-depth
        return 0
    if depth == 0:
        return evaluate(b)
    moves = list(b.legal_moves)
    if maximizing:
        val = -99999
        for m in moves:
            b.push(m); val = max(val, minimax(b, depth-1, alpha, beta, False)); b.pop()
            alpha = max(alpha, val)
            if alpha >= beta: break
        return val
    else:
        val = 99999
        for m in moves:
            b.push(m); val = min(val, minimax(b, depth-1, alpha, beta, True)); b.pop()
            beta = min(beta, val)
            if alpha >= beta: break
        return val

results = []
for m in board.legal_moves:
    board.push(m)
    val = minimax(board, 4, -99999, 99999, False)
    board.pop()
    results.append((val, m.uci()))
results.sort(reverse=True)
for r in results[:10]:
    print(r)
"}

